this.$auth.getUserInfo()
    ?.then(res => this.loggedInUser = res.fullname || res.name || res.username || res.email || res.sub || "User")
    .catch(err => console.error(err));

try {
    const headers = this.getHeaders();
    const response = await this.lontiUtilSaasAppAuthorizationApi.workflow_lonti_util_saas_app_authorization_workflow_user_SelectUserMe(
        {},
        { headers }
    );

    const user = response?.data?.user;

    if (user && Array.isArray(user.roles)) {
        const { tenantMap, roleMap } = user.roles.reduce((accumulator, role) => {
            if (role && role.tenantId && role.tenantName && role.tenantCode) {

                const simplifiedRole = {
                    name: role.name,
                    scopes: role.scopes,
                    tenantId: role.tenantId,
                    tenantName: role.tenantName,
                    tenantCode: role.tenantCode
                };
                accumulator.tenantMap[role.tenantCode] = role.tenantName;

                if (!accumulator.roleMap[role.name]) {
                    accumulator.roleMap[role.name] = [];
                }
                accumulator.roleMap[role.name].push(simplifiedRole);
            }
            return accumulator;
        }, { tenantMap: {}, roleMap: {} });
        this.saasAuth.tenants = tenantMap;
        this.saasAuth.rolesByName = roleMap;
    } else {
        throw new Error("API response is missing the expected 'user' or 'roles' data.");
    }

} catch (error) {
    console.error(`API Error in authService:`, error);
    if (error.response) {
        console.error("Server responded with:", error.response.data);
    }
    throw error;
}

// Helper function to safely construct a full URL from a base and a path
const getFullApiUrl = (base, path) => {
  if (!base || !path) {
    return null;
  }
  const cleanBase = base.endsWith('/') ? base.slice(0, -1) : base;
  const cleanPath = path.startsWith('/') ? path : `/${path}`;
  return cleanBase + cleanPath;
};

// Get the single base URL from the environment
const apiBaseUrlFromEnv = this.$env.getProperty("apiBaseUrl");

// Central validation for the base URL
if (!apiBaseUrlFromEnv || apiBaseUrlFromEnv.trim() === "") {
  console.warn("The 'apiBaseUrl' environment variable is not set. API URLs cannot be configured.");
} else {
  // Array of API endpoint configurations
  const apiEndpoints = [
    {
      path: "/api/lonti_util_saas_app_authorization/1.0",
      urlProperty: 'authApiBaseUrl',
      service: this.lontiUtilSaasAppAuthorizationApi, // Assumed to exist
      serviceName: 'lontiUtilSaasAppAuthorizationApi'
    }
  ];

  // Iterate over each configuration to set the URL and configure the service
  apiEndpoints.forEach(endpoint => {
    const fullApiUrl = getFullApiUrl(apiBaseUrlFromEnv, endpoint.path);
    this[endpoint.urlProperty] = fullApiUrl;

    if (endpoint.service && typeof endpoint.service.setServerUrl === 'function') {
      endpoint.service.setServerUrl(fullApiUrl);
    } else {
      console.warn(`The '${endpoint.serviceName}' service or its 'setServerUrl' method is not available.`);
    }
  });
}

const currentTenantCode = this.$cookies.get("x_tenant_code");
const adminRoles = this.saasAuth?.rolesByName?.['Admin'];
this.isCurrentUserAdmin = Array.isArray(adminRoles) && !!currentTenantCode &&
    adminRoles.some(role => role.tenantCode === currentTenantCode);

